"use client";

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { controlChecked, controlUnchecked } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Playful console Checkbox: a 1.125rem white key with a firm olive edge and
 * a thin slab. Checked or mixed, it becomes the orange key at a shorter
 * slab, with a bold ink tick or dash. Base UI owns the checked state, so a
 * controlled parent passes `checked` straight through.
 */
function Checkbox({
  className,
  indeterminate,
  ...props
}: WithClassName<CheckboxPrimitive.Root.Props>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      indeterminate={indeterminate}
      className={cn(
        "peer inline-flex size-[1.125rem] shrink-0 items-center justify-center rounded-md text-primary-foreground",
        controlUnchecked,
        "transition-[background-color,border-color,box-shadow] duration-fast ease-out",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        "data-[disabled]:cursor-not-allowed data-[disabled]:bg-secondary data-[disabled]:text-(--foreground-disabled) data-[disabled]:shadow-none",
        controlChecked,
        "data-[indeterminate]:border-(--primary-rim) data-[indeterminate]:bg-primary data-[indeterminate]:shadow-(--shadow-control)",
        "data-[disabled]:data-[indeterminate]:border-(--line-strong) data-[disabled]:data-[indeterminate]:bg-secondary data-[disabled]:data-[indeterminate]:shadow-none",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="flex size-full items-center justify-center text-current"
      >
        <Icon
          icon={indeterminate ? "ph:minus-bold" : "ph:check-bold"}
          aria-hidden="true"
          className="size-3"
        />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}
Checkbox.displayName = "Checkbox";

export { Checkbox };
